Lemma IoWorld3_keep352 : forall LB m m' P allocb regb cfgb schedb v q stb F ds code nr nb,
  IoWorld3 LB m (P + 384) (P + 352) allocb regb cfgb schedb v q stb F ds code nr nb ->
  munch [(P, P + 352)]%Z m m' -> wmono rsegs m m' -> hceil <= P ->
  (forall b, In b LB -> blk_addr b + blk_size b <= hceil) ->
  IoWorld3 LB m' (P + 384) (P + 352) allocb regb cfgb schedb v q stb F ds code nr nb.
Proof.
  intros LB m m' P allocb regb cfgb schedb v q stb F ds code nr nb (IOC & BS & AI & REG & CFG & SCH & SSVC & IMPLV & SB) MU WM CE HB.
  assert (D : forall a n b, In b LB -> blk_addr b <= a -> a + n <= blk_addr b + blk_size b -> disjoint_from [(P, P + 352)] a n).
  { intros a n b Hb H1 H2. pose proof (HB b Hb). cbn. lia. }
  pose proof AI as (pa & ja & INA & _). pose proof REG as (pr & j0 & j7 & INR & _). pose proof CFG as (pc & j4 & jc7 & INC & _).
  pose proof SCH as (ps & j50 & jm & j109 & je & jt & j219 & js7 & INS & _). pose proof SSVC as (pv & vj7 & INV & _).
  destruct IMPLV as [vb IMPL]. pose proof IMPL as (pq & jq7 & INQ & _ & _ & _ & _ & _ & _ & _ & VST). cbn [im_vcap im_vb im_states zlength length] in VST.
  pose proof SB as (pb & bj7 & bj16 & bj4 & INB & _ & _ & _ & _ & _ & _ & _ & FB & _). cbn [st_fb] in FB.
  unfold IoWorld3, ImplBlockV.
  split; [eapply rw_cells_transport; [exact IOC| exact MU| exact WM| cbn; lia]|].
  split; [eapply rw_cells_transport; [exact BS| exact MU| exact WM| cbn; lia]|].
  split; [eapply AllocImpl_transport; [exact AI| exact MU| exact WM| eapply D; [exact INA| cbn; lia| cbn; lia]]|].
  split; [eapply Registry_transport; [exact REG| exact MU| exact WM| eapply D; [exact INR| cbn; lia| cbn; lia]]|].
  split; [eapply ConfigSvc_transport; [exact CFG| exact MU| exact WM| eapply D; [exact INC| cbn; lia| cbn; lia]]|].
  split; [eapply Scheduler_transport; [exact SCH| exact MU| exact WM| eapply D; [exact INS| cbn; lia| cbn; lia]]|].
  split; [eapply StreamSvc_transport; [exact SSVC| exact MU| exact WM| eapply D; [exact INV| cbn; lia| cbn; lia]]|].
  split.
  - exists vb. eapply ImplBlock_transport; [exact IMPL| exact MU| exact WM| eapply D; [exact INQ| cbn; lia| cbn; unfold SZ_SPCI_IMPL; lia]|].
    cbn [im_vcap im_vb]. intros K. destruct VST as [[K0 _]|(pva & jva & INVA & _)]; [lia|]. eapply D; [exact INVA| cbn; lia| cbn; lia].
  - eapply StateBlock_transport; [exact SB| exact MU| exact WM| eapply D; [exact INB| cbn; lia| cbn; unfold SZ_SPCI_STATE; lia]|].
    cbn [st_fb]. intros NE. destruct FB as (_ & OK & _). destruct OK as [K|(pf & INF & _)]; [exact (False_ind _ (NE K))|].
    eapply D; [exact INF| cbn; lia| cbn; lia].
Qed.

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.
  Variable FT : mem -> Prop.
  Hypothesis FT_local : ft_local FT.

  Definition fzK3 (gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (P D N lo B : Z) (ra s0 s1 s2 : word) (ds : list byte) (LB : list block) (m0 : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 m (s' : PState) (errv : word) (W : fzw) (pad7 pad2 pad4 j13 j32a j8a j32b j8b : list byte),
      cfg_ms c = MS (mkR (Z_to_bv 64 P_FZ_RET_SRO) (Z_to_bv 64 P) gp tp t0 t1 t2 (Z_to_bv 64 N) (Z_to_bv 64 D)
                         (Z_to_bv 64 (P + 352)) (Z_to_bv 64 (P + 408)) (Z_to_bv 64 P) (Z_to_bv 64 (P + 456)) a4 a5 a6 a7
                         (Z_to_bv 64 u64max) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (Z_to_bv 64 P_SYNC_READ_OP) fc None m (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m /\ stk rsegs m lo P
      /\ rw_cells rsegs m (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m B
      /\ hs_RHEAP H s' (fz_LB2 N W LB) m
      /\ IoWorld3 (fz_LB2 N W LB) m (P + 384) (P + 352) (w_allocb W) (w_regb W) (w_cfgb W) (w_schedb W) (w_v W) (w_q W) (w_stb W)
                  (stream_fb N (w_A W)) ds STREAM_EOF 0 0
      /\ ImplBlock (fz_LB2 N W LB) m (w_q W) (impl_after (w_va W) (w_stb W))
      /\ (1 <= N -> rblock_range (w_A W) N /\ (w_A W + N <= w_stb W \/ w_stb W + SZ_SPCI_STATE <= w_A W))
      (* [comment removed for export] *)
      /\ rw_cells rsegs m P (ParserCoreCells pcore_init pad7 pad2)
      /\ rw_cells rsegs m (P + 80) (NodeCells (init_header_node (P + 80)) pad4)
      /\ rw_cells rsegs m (P + 112) (LNodeCells (init_lheader_node (P + 112)))
      /\ rw_cells rsegs m (P + 128) (HdrCells (mkHV 0 0 0 0 11 0))
      /\ rw_cells rsegs m (P + 168) (MBufHdrCells (P + 176) (P + 176) (P + 176) 0 0 0 0)
      /\ rw_cells rsegs m (P + 232) [C8 (wz (P + 168))]
      /\ rw_cells rsegs m (P + 240) [CB 3 [b8 0; b8 0; b8 0]; CB 13 j13]
      /\ rw_cells rsegs m (P + 256) [CB 32 j32a; C8 (wz 0); CB 8 j8a]
      /\ rw_cells rsegs m (P + 304) [CB 32 j32b; C8 (wz 0); CB 8 j8b]
      (* [comment removed for export] *)
      /\ rw_cells rsegs m (P + 408) (FlatBufCells FB_empty) /\ rw_cells rsegs m (P + 456) (ErrCodeCells EC_clear)
      /\ rw_cells rsegs m (P + 480) [C8 s2; C8 s1; C8 s0; C8 ra]
      /\ HStat FT m
      /\ xpres LB (P + 512) XH_X m0 m.

  Lemma fz_D : forall gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 (F : bvmap 5 word) (fc : bv 32)
      (P D N lo B : Z) (ra s0 s1 s2 : word) (ds : list byte) (LB : list block) (m0 : mem) (mo : Model) (c : config),
    fz_pure H P D N lo B ra LB -> tp = Z_to_bv 64 RATP ->
    fzK2 H FT gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P D N lo B ra s0 s1 s2 ds LB m0 mo c ->
    hs_SR H (fzK3 gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P D N lo B ra s0 s1 s2 ds LB m0 mo) c.
  Proof.
    intros until c. intros PU TP K2.
    pose proof PU as (AL & CEIL & LO & PB & BHI & P47 & RAE & NR & DAL & D0 & DNH & INB & DEMP & BUD & BUDC).
    unfold FUZZ_STACK in LO. hcb.
    destruct c as [ms moc]. unfold fzK2 in K2. cbn [cfg_ms cfg_model] in K2.
    destruct K2 as (t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & t3 & t4 & t5 & t6 & m & s' & errv & W & j351
                    & -> & KREL & MP & MI & ST & ERR & AUX & HP & IO3 & IMPL & BRN & FRP & FB & EC & SAV & HS & XP).
    assert (HB : forall b, In b (fz_LB2 N W LB) -> blk_addr b + blk_size b <= hceil).
    { intros b Hb. destruct (hh_blocks H HH _ _ _ b HP Hb) as (_ & _ & _ & H4 & _). exact H4. }
    eapply (hh_evt H HH); [exact KREL| |].
    { eapply fzD; [exact FRP| reflexivity| lia| lia| exact AL| exact MI]. }
    intros ms1 PO. unfold fzD_post in PO. unfold fzK3. cbn [cfg_ms cfg_model].
    destruct PO as (x0 & x1 & x2 & b4 & b5 & b6 & b7 & x3 & x4 & x5 & x6 & m1 & pad7 & pad2 & pad4 & j13 & j32a & j8a & j32b & j8b
                    & -> & MU & WM & MI1 & CORE & NODE & LNODE & HDR & MBH & RDB & FLG & CBH & CBB).
    pose proof IMPL as (pq & jq7 & INQ & _ & _ & _ & _ & _ & _ & _ & VST). cbn [im_vcap im_vb im_states impl_after zlength length] in VST.
    destruct VST as [[K _]|(pva & jva & INVA & _)]; [lia|].
    do 11 eexists. exists m1, s', errv, W, pad7, pad2, pad4, j13, j32a, j8a. exists j32b, j8b.
    split; [reflexivity|]. split; [exact KREL|]. split; [exact MP|]. split; [exact MI1|].
    split. { eapply (stk_transport_disjoint rsegs _ m m1); [exact ST| exact MU| exact WM| cbn; lia]. }
    assert (EA : errno_addr (Z_to_bv 64 RATP) = RERRNO) by (unfold RATP, RERRNO; rewrite unsigned_lit; lia).
    split. { subst tp. rewrite EA in ERR |- *. eapply (rw_cells_transport rsegs _ m m1); [exact ERR| exact MU| exact WM| unfold RERRNO; cbn; lia]. }
    split. { eapply (hh_rauxv_frame H HH); [exact AUX| exact MU| exact WM|]. unfold RAUXV_CELL in *. constructor; [cbn; lia| constructor]. }
    assert (HP1 : hs_RHEAP H s' (fz_LB2 N W LB) m1).
    { eapply (hh_RHEAP_frame H HH); [exact HP| exact MU| exact WM|]. constructor; [left; cbn; lia| constructor]. }
    split; [exact HP1|].
    split. { eapply IoWorld3_keep352; [exact IO3| exact MU| exact WM| lia| exact HB]. }
    split. { eapply (ImplBlock_transport _ _ m m1); [exact IMPL| exact MU| exact WM| |].
      - pose proof (HB _ INQ) as K. cbn in K. cbn. unfold SZ_SPCI_IMPL in *. lia.
      - cbn [im_vcap im_vb impl_after]. intros _. pose proof (HB _ INVA) as K. cbn in K. cbn. lia. }
    split; [exact BRN|].
    split; [exact CORE|]. split; [exact NODE|]. split; [exact LNODE|]. split; [exact HDR|]. split; [exact MBH|]. split; [exact RDB|].
    split; [exact FLG|]. split; [exact CBH|]. split; [exact CBB|].
    split. { eapply (rw_cells_transport rsegs _ m m1); [exact FB| exact MU| exact WM| cbn; lia]. }
    split. { eapply (rw_cells_transport rsegs _ m m1); [exact EC| exact MU| exact WM| cbn; lia]. }
    split. { eapply (rw_cells_transport rsegs _ m m1); [exact SAV| exact MU| exact WM| cbn; lia]. }
    split. { eapply HStat_munch_keep; [exact FT_local| exact HS| exact MU|]. unfold XH_LO, XH_HI. constructor; [cbn; lia| constructor]. }
    rewrite fz_LB2_eq in HP1.
    eapply (xp_lift_munch H HH s' (fz_NEW2 N W) LB m1); [exact XP| exact MU| exact WM| lia| exact HP1|].
    constructor; [cbn; intros a Ha; left; left; lia| constructor].
  Qed.
End W.
End HCW.
